/// Read-only state of the `showcase` engine, mirrored from Rust.
@MainActor
final class BernEngine: BernObservableObject {
    static let shared = BernEngine()

    /// The most recent button activation.
    @Published
    private(set) var lastAction: Optional<App_Action> = nil
    /// How many gallery buttons were activated.
    @Published
    private(set) var activations: Int64 = Int64(0)
    /// Committed volume between 0 and 100.
    @Published
    private(set) var volume: Double = Double(0.0)
    /// Sample library items.
    @Published
    private(set) var items: [App_Item] = []
    /// Clip featured on the media page.
    @Published
    private(set) var featured: App_Clip = App_Clip.pattern
    /// Source of the featured clip; the media page's video follows it.
    @Published
    private(set) var featuredSource: App_MediaSource = App_MediaSource(url: "")
    /// Saved display name, edited in the settings window.
    @Published
    private(set) var displayName: String = ""

    func bernApply(_ field: UInt32, _ reader: inout BernReader) throws {
        switch field {
            case 0: lastAction = try Optional<App_Action>(bern: &reader)
            case 1: activations = try Int64(bern: &reader)
            case 2: volume = try Double(bern: &reader)
            case 3: items = try [App_Item](bern: &reader)
            case 4: featured = try App_Clip(bern: &reader)
            case 5: featuredSource = try App_MediaSource(bern: &reader)
            case 6: displayName = try String(bern: &reader)
            default: throw BernDecodeError(message: "unknown state field \(field)")
        }
    }

    /// Record that a gallery button was activated.
    func record(_ action: App_Action, from window: BernWindowContext?, completion: (@MainActor (BernCommandFailure?) -> Void)? = nil) {
        BernHost.shared.dispatch(0, window: window?.id, encode: { writer in
            action.encode(bern: &writer)
        }, completion: completion)
    }

    /// Commit the volume slider.
    func setVolume(_ value: Double, from window: BernWindowContext?, completion: (@MainActor (BernCommandFailure?) -> Void)? = nil) {
        BernHost.shared.dispatch(1, window: window?.id, encode: { writer in
            value.encode(bern: &writer)
        }, completion: completion)
    }

    /// Add a sample item and return its id.
    func addItem(_ kind: App_ItemKind, from window: BernWindowContext?, completion: (@MainActor (BernCommandFailure?) -> Void)? = nil) {
        BernHost.shared.dispatch(2, window: window?.id, encode: { writer in
            kind.encode(bern: &writer)
        }, completion: completion)
    }

    /// Remove an item by id.
    func removeItem(_ id: Int64, from window: BernWindowContext?, completion: (@MainActor (BernCommandFailure?) -> Void)? = nil) {
        BernHost.shared.dispatch(3, window: window?.id, encode: { writer in
            id.encode(bern: &writer)
        }, completion: completion)
    }

    /// Feature a clip on the media page.
    func feature(_ clip: App_Clip, from window: BernWindowContext?, completion: (@MainActor (BernCommandFailure?) -> Void)? = nil) {
        BernHost.shared.dispatch(4, window: window?.id, encode: { writer in
            clip.encode(bern: &writer)
        }, completion: completion)
    }

    /// Save the display name: 1 to 40 characters, not only spaces.
    func setDisplayName(_ name: String, from window: BernWindowContext?, completion: (@MainActor (BernCommandFailure?) -> Void)? = nil) {
        BernHost.shared.dispatch(5, window: window?.id, encode: { writer in
            name.encode(bern: &writer)
        }, completion: completion)
    }

    /// Library items whose category name contains `text`, in any language; an empty text lists every item. Broad searches answer later than narrow ones, as a real index would.
    func searchLibrary(_ text: String, from window: BernWindowContext?, completion: (@MainActor (BernCommandFailure?) -> Void)? = nil) {
        BernHost.shared.dispatch(6, window: window?.id, encode: { writer in
            text.encode(bern: &writer)
        }, completion: completion)
    }
