// MARK: - Windows

/// Root of the `main` window.
@MainActor
struct BernWindow0: View {
    @StateObject private var context = BernWindowContext(kind: 0, kindID: "main", isSettings: false, sessions: [App_MainDraft()])
    @EnvironmentObject private var bernEngine: BernEngine
    @ObservedObject private var bernLanguage = BernLanguage.shared
    @ObservedObject private var bernTheme = BernThemeState.shared
    private var bernWindow: BernWindowContext { context }
    private var session_MainDraft: App_MainDraft { context.session(App_MainDraft.self) }

    var body: some View {
        BernWindowRoot(context: context) {
            BernSearchPaletteHost {
                AppView_main_window()
            }
        }
        .bernEnvironment(context.session(App_MainDraft.self))
        .frame(minWidth: 720.0, minHeight: 480.0)
        .onAppear { context.closeCheck = bernCloseCheck() }
    }

    private func bernCloseCheck() -> BernCloseCheck {
        let context = self.context
        return BernCloseCheck(
            needsConfirmation: { [weak context] in
                guard let context else { return false }
                let session_MainDraft = context.session(App_MainDraft.self)
                return (session_MainDraft.notes) != ("")
            },
            message: { [weak context] in
                guard context != nil else { return "" }
                return BernText.string("app.0.0.close_message")
            },
            save: nil
        )
    }
}

/// Root of the `settings` window.
@MainActor
struct BernWindow1: View {
    @StateObject private var context = BernWindowContext(kind: 1, kindID: "settings", isSettings: true, sessions: [App_SettingsDraft()])
    @EnvironmentObject private var bernEngine: BernEngine
    @ObservedObject private var bernLanguage = BernLanguage.shared
    @ObservedObject private var bernTheme = BernThemeState.shared
    private var bernWindow: BernWindowContext { context }
    private var session_SettingsDraft: App_SettingsDraft { context.session(App_SettingsDraft.self) }

    var body: some View {
        BernWindowRoot(context: context) {
            BernSearchPaletteHost {
                AppView_settings_window()
            }
        }
        .bernEnvironment(context.session(App_SettingsDraft.self))
        .frame(width: 520.0)
        .scrollDisabled(true)
        .fixedSize(horizontal: false, vertical: true)
        .onAppear { context.closeCheck = bernCloseCheck() }
    }

    private func bernCloseCheck() -> BernCloseCheck {
        let context = self.context
        let bernEngine = self.bernEngine
        return BernCloseCheck(
            needsConfirmation: { [weak context] in
                guard let context else { return false }
                let session_SettingsDraft = context.session(App_SettingsDraft.self)
                return ((session_SettingsDraft.displayName) != ("")) && ((session_SettingsDraft.displayName) != (bernEngine.displayName))
            },
            message: { [weak context] in
                guard context != nil else { return "" }
                return BernText.string("app.0.1.close_message")
            },
            save: { [weak context] done in
                guard let context else { done(BernCommandFailure(code: "stale_window", message: "The hosting window has closed")); return }
                let session_SettingsDraft = context.session(App_SettingsDraft.self)
                bernEngine.setDisplayName(session_SettingsDraft.displayName, from: context, completion: done)
            }
        )
    }
}

@main
struct BernApplication: App {
    @NSApplicationDelegateAdaptor(BernAppDelegate.self) private var delegate
    @ObservedObject private var bernLanguage = BernLanguage.shared

    init() {
        BernHost.shared.start(fingerprint: 0x2490f5e67cff9fac, kinds: [BernWindowKind(id: "main", title: "app.0.0.title", isSettings: false, isDialog: false, defaultSize: CGSize(width: 920.0, height: 640.0)), BernWindowKind(id: "settings", title: "app.0.1.title", isSettings: true, isDialog: false, defaultSize: nil)], primary: "main") { field, reader in
            try BernEngine.shared.bernApply(field, &reader)
        }
    }

    var body: some Scene {
        SwiftUI.Window(SwiftUI.Text(verbatim: BernText.string("app.0.0.title")), id: "main") {
            BernWindow0()
                .bernEnvironment(BernEngine.shared)
        }
        .defaultSize(width: 920.0, height: 640.0)
        .windowResizability(.contentMinSize)
        SwiftUI.Settings {
            BernWindow1()
                .bernEnvironment(BernEngine.shared)
        }
    }
}
